/**
 * Returns the base URL for the AI provider.
 *
 * Priority (independence-first):
 *   1. IVX_OPENAI_API_KEY is set  → api.openai.com/v1 (owner's direct key)
 *   2. IVX_ANTHROPIC_API_KEY is set → api.anthropic.com/v1 (owner's direct key)
 *   3. IVX_AI_GATEWAY_URL explicitly set (non-Rork) → that URL
 *   4. Auto-detect from key prefix (vck_ → Vercel, sk- → OpenAI direct)
 *
 * This ensures that when the owner provides their own OpenAI key, the runtime
 * routes directly to OpenAI — even if a stale IVX_AI_GATEWAY_URL pointing at
 * the Vercel gateway is still set on the host.
 */
function getIVXAIGatewayRootUrl(): string {
  // Owner-owned keys take absolute priority — route to the matching direct API
  if (readTrimmed(process.env.IVX_OPENAI_API_KEY)) {
    return OPENAI_DIRECT_BASE;
  }
  if (readTrimmed(process.env.IVX_ANTHROPIC_API_KEY)) {
    return 'https://api.anthropic.com/v1';
  }
  // Explicit gateway URL override (only if not a blocked external domain)
  const configured = readTrimmed(process.env.IVX_AI_GATEWAY_URL);
  if (configured && !isBlockedDomain(configured)) {
    return configured;
  }
  // Auto-detect from key prefix
  const key = getIVXAIGatewayApiKey();
  if (key && isVercelGatewayKey(key)) {
    return VERCEL_AI_GATEWAY_BASE;
  }
  return OPENAI_DIRECT_BASE;
}

function buildGatewayBaseUrl(rootUrl: string): string | null {
  const trimmed = readTrimmed(rootUrl).replace(/\/+$/, '');
  return trimmed || null;
}

function getGatewayBaseUrl(): string | null {
  return buildGatewayBaseUrl(getIVXAIGatewayRootUrl());
}

function getGatewayBaseUrlCandidates(): string[] {
  const configured = getGatewayBaseUrl();
  // Auto-detect fallback candidate based on key prefix.
  // If the primary is a Vercel key (vck_), the fallback candidate is OpenAI direct.
  // If the primary is an OpenAI key (sk-), the fallback candidate is the Vercel gateway.
  // This ensures both endpoints are tried if the key/URL auto-detection mismatches.
  const key = getIVXAIGatewayApiKey();
  const fallbackCandidate = key && isVercelGatewayKey(key)
    ? buildGatewayBaseUrl(OPENAI_DIRECT_BASE)
    : buildGatewayBaseUrl(VERCEL_AI_GATEWAY_BASE);
  // Independence guard: any candidate that resolves to a blocked external
  // domain is filtered out, so a stale env var cannot re-route there.
  const candidates = [configured, fallbackCandidate].filter((c): c is string => c !== null && !isBlockedDomain(c));
  return [...new Set(candidates)];
}

function ensureIVXAIGatewayEnvironment(): void {
  const apiKey = getIVXAIGatewayApiKey();
  if (!apiKey) {
    throw new Error(
      'IVX AI runtime is not configured. Set OPENAI_API_KEY on the backend host.',
    );
  }
