for (let i = 0; i < questions.length; i += 1) {
  const q = questions[i];
  if (completedIds.has(q.id)) {
    console.log(`[${i + 1}/${questions.length}] ${q.id} SKIP (already completed)`);
    continue;
  }
  const sessionId = `narrative-qa-${q.id}`;
  let attempt = 0;
  let success = false;
  while (!success && attempt < 5) {
    attempt += 1;
    try {
      const { data, latencyMs, status, rlRemaining, rlReset } = await chat({ message: q.prompt, sessionId });
      if (rlRemaining === '0') {
        const resetAt = rlReset ? new Date(rlReset) : null;
        const waitMs = resetAt ? Math.max(0, resetAt.getTime() - Date.now() + 500) : 30000;
        console.log(`[${i + 1}/${questions.length}] ${q.id} rate limited; waiting ${Math.round(waitMs)}ms until ${resetAt?.toISOString()}`);
        await sleep(waitMs);
        continue;
      }
      results.push({
        id: q.id,
        category: q.category,
        prompt: q.prompt,
        sessionId,
        status,
        latencyMs: Math.round(latencyMs),
        source: data.source ?? null,
        model: data.model ?? null,
        answer: data.answer ?? '',
        ok: data.ok ?? false,
        rateLimitRemaining: data.rateLimitRemaining ?? rlRemaining,
        rateLimitResetAt: data.rateLimitResetAt ?? rlReset,
        timestamp: data.timestamp ?? new Date().toISOString(),
      });
      console.log(`[${i + 1}/${questions.length}] ${q.id} ${q.category} source=${data.source ?? 'unknown'} latency=${Math.round(latencyMs)}ms len=${(data.answer ?? '').length}`);
      success = true;
    } catch (err) {
      console.log(`[${i + 1}/${questions.length}] ${q.id} attempt ${attempt} ERROR: ${err instanceof Error ? err.message : String(err)}`);
      await sleep(5000);
    }
  }
  if (!success) {
    results.push({
      id: q.id,
      category: q.category,
      prompt: q.prompt,
      sessionId,
      status: 0,
      latencyMs: 0,
      source: 'error',
      model: null,
      answer: 'Failed after 5 attempts',
      ok: false,
      rateLimitRemaining: null,
      rateLimitResetAt: null,
      timestamp: new Date().toISOString(),
    });
  }
  await saveTranscript(results);
  // Conservative pacing to avoid rolling-window rate limits
  await sleep(4000);
}

