{"filePath": "qa/narrative-qa-battery.mjs", "content": "/**
 * IVX IA Chat Senior Intelligence & Narrative QA Battery
 * Runs against production /api/public/chat, captures exact responses.
 * Rate-limit-aware with resume capability.
 */

const API_BASE = 'https://api.ivxholding.com';
const ENDPOINT = `${API_BASE}/api/public/chat`;
const CLIENT_ID = 'narrative-qa-runner';
const TRANSCRIPT_PATH = 'qa/narrative-qa-transcript.json';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function loadPartial() {
  try {
    const raw = await Bun.file(TRANSCRIPT_PATH).text();
    const data = JSON.parse(raw);
    if (Array.isArray(data.results)) return data.results;
  } catch {
    // no partial transcript
  }
  return [];
}

async function saveTranscript(results) {
  await Bun.write(TRANSCRIPT_PATH, JSON.stringify({ runAt: new Date().toISOString(), total: results.length, results }, null, 2));
}

async function chat({ message, sessionId }) {
  const startedAt = performance.now();
  const res = await fetch(ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ message, clientId: CLIENT_ID, sessionId }),
  });
  const latencyMs = performance.now() - startedAt;
  const data = await res.json();
  const rlRemaining = res.headers.get('x-ratelimit-remaining') ?? res.headers.get('RateLimit-Remaining') ?? null;
  const rlReset = res.headers.get('x-ratelimit-reset') ?? res.headers.get('RateLimit-Reset') ?? null;
  return { data, latencyMs, status: res.status, rlRemaining, rlReset };
}

